#!/usr/bin/env pwsh
<#
.SYNOPSIS
    Parses PowerShell scripts with the Windows PowerShell 5.1 parser.

.DESCRIPTION
    Two checks that PSScriptAnalyzer cannot make, since CI runs it under
    PowerShell 7, whose parser accepts syntax 5.1 rejects (&&, ||, ??, ?.,
    the ternary operator):

    1. Every tracked *.ps1 file parses under 5.1.
    2. The profile assembled from src/pwsh/manifest.txt, joined the way
       scripts/install.ps1 joins it, parses under 5.1. One parse error
       anywhere in it stops the whole installed profile from loading, and
       some errors only exist once the parts are concatenated.

    Refuses to run under PowerShell 7: the point is the 5.1 parser.

    When GITHUB_ACTIONS is "true", findings are emitted as workflow annotations
    so they land on the PR diff.

.PARAMETER Path
    Explicit files to parse instead of the tracked *.ps1 set. The assembled
    profile is checked either way.

.EXAMPLE
    powershell.exe -NoProfile -File .github/scripts/check-syntax-pwsh.ps1
#>
#Requires -Version 5.1

[CmdletBinding()]
param(
    [string[]] $Path
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

if ($PSVersionTable.PSEdition -ne 'Desktop') {
    Write-Output "This check needs the Windows PowerShell 5.1 parser: run it with powershell.exe, not PowerShell $($PSVersionTable.PSVersion)."
    exit 1
}

Set-Location (git rev-parse --show-toplevel)

$script:failures = 0

# Per-file findings, so an error inside a part is not reported a second time
# by the assembled-profile pass.
$script:seen = @{}

function Write-Finding {
    param(
        [Parameter(Mandatory)] [string] $File,
        [int] $Line = 1,
        [int] $Column = 1,
        [Parameter(Mandatory)] [string] $Message
    )

    $script:failures++

    # Annotations are single-line: flatten any wrapped parser message.
    $flat = ($Message -replace '\s+', ' ').Trim()

    if ($env:GITHUB_ACTIONS -eq 'true') {
        Write-Output "::error file=${File},line=${Line},col=${Column}::${flat}"
    }
    else {
        Write-Output "${File}:${Line}:${Column}: error: ${flat}"
    }
}

# --- 1. Each file on its own ------------------------------------------------

if (-not $Path) {
    # --others picks up files not yet committed; the existence test drops paths
    # that are still in the index but already deleted from the working tree.
    $Path = @(git ls-files --cached --others --exclude-standard '*.ps1')
}
$targets = @($Path | Where-Object { Test-Path -LiteralPath $_ -PathType Leaf })

foreach ($target in $targets) {
    $file = $target -replace '\\', '/' -replace '^\./', ''
    $parseErrors = $null
    $fullPath = (Resolve-Path -LiteralPath $target).Path
    [void][System.Management.Automation.Language.Parser]::ParseFile($fullPath, [ref]$null, [ref]$parseErrors)

    foreach ($parseError in $parseErrors) {
        $line = $parseError.Extent.StartLineNumber
        $column = $parseError.Extent.StartColumnNumber
        $script:seen["${file}|${line}|${column}|$($parseError.ErrorId)"] = $true
        Write-Finding -File $file -Line $line -Column $column `
            -Message "$($parseError.ErrorId): $($parseError.Message)"
    }
}

Write-Output "Windows PowerShell $($PSVersionTable.PSVersion) parser: $($targets.Count) file(s) parsed."

# --- 2. The assembled profile -----------------------------------------------

$partDir = 'src/pwsh'
$manifestPath = "$partDir/manifest.txt"
$utf8 = New-Object System.Text.UTF8Encoding $false

if (-not (Test-Path -LiteralPath $manifestPath -PathType Leaf)) {
    Write-Finding -File $manifestPath -Message 'manifest is missing: cannot assemble the profile.'
}
else {
    $manifest = [System.IO.File]::ReadAllText((Resolve-Path -LiteralPath $manifestPath).Path, $utf8)

    # Same parsing as install.ps1: drop comments and blanks; Trim() also
    # absorbs the CR of a CRLF manifest.
    $parts = @(
        $manifest -split "`n" |
            ForEach-Object { ($_ -split '#')[0].Trim() } |
            Where-Object { $_ }
    )

    # A two-line header, as install.ps1 writes, so line numbers in the
    # assembled text match an installed profile_extra.ps1.
    $chunks = New-Object System.Collections.Generic.List[string]
    $chunks.Add("# Generated by common-shell.`n# Assembled by check-syntax-pwsh.ps1.")

    # Where each part lands in the assembled text, to map errors back to it.
    # The first part starts after the header and one blank separator line.
    $origins = New-Object System.Collections.Generic.List[object]
    $nextLine = 4
    $complete = $true

    foreach ($part in $parts) {
        $partPath = "$partDir/$part"
        if (-not (Test-Path -LiteralPath $partPath -PathType Leaf)) {
            Write-Finding -File $manifestPath -Message "lists $part, which does not exist in ${partDir}/: cannot assemble the profile."
            $complete = $false
            continue
        }

        # Same normalisation as install.ps1: no BOM, LF line endings, no
        # trailing newline, so the join controls the separator exactly.
        $content = [System.IO.File]::ReadAllText((Resolve-Path -LiteralPath $partPath).Path, $utf8)
        $chunk = (($content.TrimStart([char]0xFEFF)) -replace "`r`n", "`n").TrimEnd("`n")
        $chunks.Add($chunk)

        $lineCount = ($chunk -split "`n").Count
        $origins.Add([pscustomobject]@{ File = $partPath; Start = $nextLine; End = $nextLine + $lineCount - 1 })
        $nextLine += $lineCount + 1
    }

    if ($parts.Count -eq 0) {
        Write-Finding -File $manifestPath -Message 'manifest lists no files: cannot assemble the profile.'
    }
    elseif ($complete) {
        $body = ($chunks -join "`n`n") + "`n"
        $parseErrors = $null
        [void][System.Management.Automation.Language.Parser]::ParseInput($body, [ref]$null, [ref]$parseErrors)

        foreach ($parseError in $parseErrors) {
            $assembledLine = $parseError.Extent.StartLineNumber
            $column = $parseError.Extent.StartColumnNumber
            $origin = $origins |
                Where-Object { $assembledLine -ge $_.Start -and $assembledLine -le $_.End } |
                Select-Object -First 1

            if ($origin) {
                $file = $origin.File
                $line = $assembledLine - $origin.Start + 1
            }
            else {
                # Past the last part, e.g. an unclosed block reported at EOF.
                $file = $manifestPath
                $line = 1
            }

            if ($script:seen.ContainsKey("${file}|${line}|${column}|$($parseError.ErrorId)")) {
                continue
            }

            Write-Finding -File $file -Line $line -Column $column `
                -Message "assembled profile, line ${assembledLine}: $($parseError.ErrorId): $($parseError.Message)"
        }

        Write-Output "Assembled profile: $($parts.Count) part(s), $($nextLine - 2) line(s) parsed."
    }
}

if ($script:failures -gt 0) {
    Write-Output "Windows PowerShell 5.1 parser reported $($script:failures) error(s)."
    exit 1
}

Write-Output 'Windows PowerShell 5.1 parser: clean.'
exit 0
